import json,hashlib,gzip,shutil
from pathlib import Path
out=Path(__file__).resolve().parent
info=json.loads((out/'analysis.json').read_text());pins=json.loads((out/'pins.json').read_text());moves=json.loads((out/'moved-findings.json').read_text())
def link(name):
 p=out/name
 return '['+name+']('+name+('.gz' if not p.exists() and Path(str(p)+'.gz').exists() else '')+')'
lines=['# findAncestor compiler bar census','', 'Task 448a51k. Report-only comparison on one adapted TypeScript 6.0.3 tree.','', '| Side | Compiler pin | First marked catalogue unit | Attempted unit | Location |', '| --- | --- | ---: | ---: | --- |']
for side in ['base','head']:
 r=info[side];lines.append(f"| {side} | `{pins[side]}` | {r['onset_ordinal']} | {r['onset_attempted_ordinal']} | `{r['onset_unit']}` ({r['onset_name']}) |")
scan=info['scan_moved_counts'];scanhead=sum(scan['head'].values())
lines+=['',f"The compiler bar {'passes' if scanhead==0 else 'fails'} before the earlier onset: {scanhead} changed refusal-scan rows there. Changes at or after onset are classified as relation-limit noise under the requested rule. This classification does not establish that every later change was caused by the limit.",'', '## Method','',f"Base `{pins['base']}` was fetched explicitly by full SHA after the server rejected its abbreviation. Both named reference branches and main were fetched. Head `{pins['head']}` has base as its sole parent. Its only changed paths are `internal/lower/overload_predicate_result.go` and its test; no `stage3/adapt` path changes. See [pins](pins.json) and fetch logs.",'', 'Read c6f6688c, `stage3/census/find-ancestor-63c11488/REPORT.md`, and copied its guarded own-pin entry-overlay, shared-input, parallel-run and separate checkpoint-ref method. No adaptations were carried. `source /workspace/adamic-tools/env.sh`, `bash cloud/setup.sh`, and `npm ci --prefix stage3/api` completed successfully. `ADAMIC_TYPESCRIPT_SOURCE` names the checkout at `050880ce59e30b356b686bd3144efe24f875ebc8`. Base `stage3/apply.sh` built one tree at `/workspace/scratch/bar-adapted`. Both sides use exactly those bytes; their hashes were checked again after the runs. See [apply log](apply.log), [patch set](patch-set.md), '+link('source-hashes.json')+', and [binary provenance](provenance.json).','', 'Each compiler was built from its own pin with the pinned shared checker and its own guarded latent plus entry overlay. Both ran first-error mode on `src/tsc/tsc.ts`, simultaneously, with `LATENT_ASSERT_NO_OUTPUT=1`, `LATENT_RELATION_PER_UNIT=1`, `GOMEMLIMIT=5GiB`, and `GOGC=70`. Whole stdout/stderr logs and streams are retained. The process wrapper reports the child exit code and cleans its process group; a 30-minute lack of progress terminates a stalled child. Unit and relation-query timings are separate evidence. No backend or native output is run.','', 'Catalogue ordinals are one-based in the original stream file/unit order, including deferred declarations. Attempted ordinals count the per-unit relation probes only. Onset includes the unit whose post-lowering check first reports overflow. Every moved source row is classified by its recorded unit against the earlier catalogue onset. Full reasons drive the exact comparison; the requested lists use `reason[:110]`, sorted and unique. Truncation can hide differences, so exact rows and the literal list diff are both retained.','', 'The pinned `stage3/census/pair/pair.py` expects source coordinates for every finding and does not accept the relation trailer at `where: program`. Its explicitly preserved pair-input copies omit only the trailer and each unit\'s observational `relation_overflow` field; all source findings, eligibility, units, and headers remain. The whole original streams drive onset classification and the separate run-end relation comparison. Pairing used the pinned stock TypeScript package. This projection changes no production or pair-tool source.','', '## Counts','', '| Moved exact finding rows | Removed from base | Added on head | Total |', '| --- | ---: | ---: | ---: |']
for c,counts in info['moved_counts'].items():lines.append(f"| {c} | {counts['base']} | {counts['head']} | {sum(counts.values())} |")
lines+=['', '| Moved refusal-scan rows | Removed from base | Added on head |', '| --- | ---: | ---: |']
for c,counts in scan.items():lines.append(f"| {c} | {counts['base']} | {counts['head']} |")
lines+=['', '| Side | Files | Catalogue units | Probed units | Exact finding rows | Truncated list rows | Checker diagnostics |', '| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for s in ['base','head']:
 r=info[s];lines.append(f"| {s} | {r['files']} | {r['catalogued_units']} | {r['probed_units']} | {info['exact_finding_rows'][s]} | {info['finding_list_rows'][s]} | {len(r['diagnostics'])} |")
lines+=['', 'Counts are unique `(unit, phase, kind, site, full reason)` rows. Removed and added rows are separate observations, not paired causal transitions. All finding kinds are retained. Equal rows are excluded from moved counts.','', '## Every head row in full','', 'Format: `side | catalogue unit number | unit | phase | kind | site | full reason`.','', '```text']
headrows=[r for r in moves if r['category']=='head'];lines += [r['side']+' | '+str(r['unit_ordinal'])+' | '+r['row'] for r in headrows] or ['none'];lines+=['```','', '## Relation-limit evidence','']
for s in ['base','head']:
 lines += [s+':','', '```json',json.dumps(info[s]['relation_report'],indent=2),'```','']
lines += ['Every moved noise row is listed with its catalogue unit and full unit location in '+link('relation-limit-noise.txt')+'. All classes, full findings and ordinals are in '+link('moved-findings.json')+'. The run-end relation report is compared separately as the relation-limit finding itself.','', '## Evidence and validation','', '- Whole streams: '+link('base-entry-run.jsonl')+', '+link('head-entry-run.jsonl')+'.','- Whole stderr/stdout logs: '+link('base-entry-run.log')+', '+link('head-entry-run.log')+'.','- Requested sorted unique lists: '+link('findings-base.txt')+', '+link('findings-head.txt')+'; literal '+link('findings.diff')+'.','- Source-only pair inputs: '+link('base-pair-input.jsonl.gz')+', '+link('head-pair-input.jsonl.gz')+'.','- Paired output: '+link('entry-paired.json')+', '+link('entry-paired.md')+'.','- Exact onset and count analysis: '+link('analysis.json')+'.','- Existing pair suite: all 15 tests passed. Both own-pin overlay relation/stream tests passed; logs and child statuses are retained.','', '| Run | Own child exit | Wall seconds | Peak RSS MiB |', '| --- | ---: | ---: | ---: |']
for s in ['base','head']:
 name=s+'-entry-run';status=json.loads((out/(name+'.status.json')).read_text());timing=json.loads((out/(name+'.time.json')).read_text());lines.append(f"| {s} | {status['exit']} | {status['wall_seconds']} | {timing['peak_rss_kib']/1024:.1f} |")
lines+=['', 'Checkpoint push receipts and full push logs are retained for each completed stream, on separate `typescript/find-ancestor-bar-census-checkpoint-*` refs. The final branch contains one report-only commit directly on c1e9379e. No main ref or force push is used.','']
text='\n'.join(lines);assert '\u2013' not in text and '\u2014' not in text
(out/'REPORT.md').write_text(text)
for p in sorted(out.rglob('*')):
 if p.is_file() and p.suffix!='.gz' and p.stat().st_size>1000000:
  with p.open('rb') as a,gzip.open(str(p)+'.gz','wb') as b:shutil.copyfileobj(a,b)
  p.unlink()
# Refresh links after size-based compression.
p=out/'REPORT.md';text=p.read_text()
import re
text=re.sub(r'\]\(([^)]+)\)',lambda m:']('+m[1]+('.gz' if not (out/m[1]).exists() and (out/(m[1]+'.gz')).exists() else '')+')',text);p.write_text(text)
(out/'SHA256SUMS').write_text(''.join(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+str(p.relative_to(out))+'\n' for p in sorted(out.rglob('*')) if p.is_file() and p.name!='SHA256SUMS'))
print('report child_exit=0')
